{
  "facts": [
    {
      "topic": "target_route",
      "statement": "The entry uses FUZZ_setRandomParameters before streaming compression, then calls ZSTD_compressStream2 with continue, flush, and end directives. It decompresses the resulting frames and checks their size and content.",
      "evidence": [
        {
          "unit_id": "u-9dc9e88ae722c8cbe085",
