      ],
      "absence_claim": true,
      "audited_unit_ids": [
        "u-9dc9e88ae722c8cbe085",
        "u-194debf8ea4cd55b47ba"
      ]
    },
    {
      "topic": "configuration",
      "statement": "The supplied build recipe delegates the fuzz build to ./fuzz.py build all. It does not supply the delegated target flags or effective compression log bounds.",
      "evidence": [
        {
          "unit_id": "u-043cf5aa9ced10a35cb6",
          "start_line": 19,
          "end_line": 24,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": true,
      "audited_unit_ids": [
        "u-043cf5aa9ced10a35cb6"
      ]
    },
    {
      "topic": "counterevidence",
      "statement": "The source checks compression parameters before adjustment, and the effective maximum constants are referenced but not defined in the supplied adjustment functions. Thus these lines alone do not establish the frozen condition that a distinct window or hash log above 15 is supported under this build.",
      "evidence": [
        {
          "unit_id": "u-facf31de921eddbcf157",
