        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    }
  ],
  "missing_information": [
    "Definitions and effective build values of ZSTD_WINDOWLOG_MAX, ZSTD_HASHLOG_MAX, and ZSTD_WINDOWLOG_ABSOLUTEMIN, plus the bounds enforced by ZSTD_checkCParams.",
    "The delegated fuzz build settings that determine whether a valid streaming compression configuration above log 15 is supported.",
    "The ZSTD_adjustCParams and ZSTD_CCtx_init_compressStream2 call paths needed to confirm how generated parameters become effective streaming parameters."
  ],
  "requested_symbols": [
    "ZSTD_WINDOWLOG_MAX",
    "ZSTD_HASHLOG_MAX",
    "ZSTD_WINDOWLOG_ABSOLUTEMIN",
    "ZSTD_checkCParams",
    "ZSTD_adjustCParams",
    "ZSTD_CCtx_init_compressStream2"
  ],
  "requested_paths": [
    "tests/fuzz/fuzz.py",
    "tests/fuzz/Makefile",
    "lib/libzstd.mk"
  ]
}
